-- Skeleton checks for 57 API-callable functions that no test names (generated by tools/sweep/fix/gen_test_skeleton.py from out/untested_functions.json
-- and supabase/grants.txt). A regression guard: rights as filed, search_path pinned, signed-out refused. Behaviour checks per function are still to be written.
-- Rolled back like every script in supabase/tests.
do $sweep$
declare
  v_log text := 'setup ok'; r record; bad text;
begin
  for r in select * from (values
    ('admin_reset_password(uuid)', false, true, true, true, true),
    ('admin_sees_case(uuid,complaint_category,uuid)', false, true, true, true, true),
    ('admin_sees_category(complaint_category)', false, true, true, true, true),
    ('admin_sees_dispatch(uuid)', false, true, true, true, false),
    ('admin_sees_report(uuid)', false, true, true, true, true),
    ('admin_update_user(uuid,text,text)', false, true, true, true, false),
    ('assert_not_client(text)', false, true, false, true, false),
    ('assignable_tanods(uuid)', false, true, false, true, false),
    ('cancel_admin_handover()', false, true, true, true, true),
    ('case_committee(reports)', false, true, true, true, false),
    ('chain_account_audit()', true, true, true, true, false),
    ('chain_status_log()', true, true, true, true, false),
    ('clear_password_change_flag()', false, true, true, true, true),
    ('confirm_synthetic_auth_email()', true, true, true, true, false),
    ('dispatch_on_file()', true, true, true, true, false),
    ('display_name(text)', true, true, false, true, false),
    ('enforce_daily_report_limit()', true, true, true, true, true),
    ('enforce_media_cap()', true, true, false, true, false),
    ('extensions_used(uuid)', false, true, true, true, false),
    ('guard_last_admin()', true, true, false, true, false),
    ('guard_privileged_user_fields()', true, true, false, true, true),
    ('handle_new_auth_user()', true, true, true, true, false),
    ('is_barangay_media_url(text)', false, true, false, true, false),
    ('is_evidence_media_url(text)', false, true, false, true, false),
    ('is_full_viewer()', false, true, true, true, false),
    ('is_super_admin()', false, true, true, true, false),
    ('is_within_barangay(double precision,double precision)', false, true, false, true, false),
    ('location_is_fresh(timestamp with time zone)', false, true, false, true, false),
    ('my_admin_handover_status()', false, true, false, true, true),
    ('my_resolution_authors(uuid[])', false, true, true, true, true),
    ('my_retirement_status()', false, true, false, true, true),
    ('my_role()', false, true, true, true, true),
    ('nearest_available_tanod(uuid)', false, true, false, true, false),
    ('places_norm(text)', true, true, false, true, false),
    ('places_status()', false, true, true, true, false),
    ('promote_to_admin(uuid,text,integer,user_role)', false, true, true, true, true),
    ('refuse_audit_write()', true, true, false, true, false),
    ('register_device_token(text,text)', false, true, true, true, true),
    ('release_case(uuid)', false, true, true, true, true),
    ('request_ocr_rescan(uuid)', false, true, true, true, false),
    ('reset_admin_password(uuid)', false, true, true, true, true),
    ('reset_verification_overdue_mark()', true, true, false, true, false),
    ('resident_abuse_reports(uuid)', false, true, true, true, false),
    ('resident_remark(text,boolean)', true, true, false, true, false),
    ('set_accept_deadline()', true, true, false, true, false),
    ('set_notification_mute(notification_kind,boolean)', false, true, true, true, true),
    ('set_report_deadline()', true, true, false, true, false),
    ('set_report_location_label(uuid,text)', false, true, true, true, true),
    ('set_verification_deadline()', true, true, false, true, false),
    ('step_down_as_admin(user_role)', false, true, true, true, true),
    ('sync_dispatchable()', true, true, false, true, false),
    ('system_usage()', false, true, true, true, false),
    ('tanod_dispatch_cap()', true, true, false, true, false),
    ('touch_settings()', true, true, false, true, true),
    ('touch_updated_at()', true, true, false, true, false),
    ('unregister_device_token(text)', false, true, true, true, true),
    ('verify_user_account(uuid,text,text)', false, true, true, true, true)
  ) as t(sig, anon_call, auth_call, secdef, pinned, reads_uid)
  loop
    begin
      perform r.sig::regprocedure;
      if has_function_privilege('anon', r.sig::regprocedure, 'execute') <> r.anon_call then raise exception 'anon right differs from grants.txt'; end if;
      if has_function_privilege('authenticated', r.sig::regprocedure, 'execute') <> r.auth_call then raise exception 'authenticated right differs from grants.txt'; end if;
      if r.secdef and not r.pinned then raise exception 'SECURITY DEFINER without a pinned search_path'; end if;
      if r.reads_uid and r.anon_call then raise exception 'reads auth.uid() but a signed-out caller may run it'; end if;
    exception when others then bad := coalesce(bad || E'
', '') || 'FAIL ' || r.sig || ': ' || sqlerrm;
    end;
  end loop;
  v_log := v_log || E'
' || coalesce(bad, 'ok  all 57 functions: exist, rights match grants.txt, search_path pinned, signed-out refused where auth.uid() is read');
  raise exception E'SWEEP-ROLLBACK
%', v_log;
end $sweep$;
